        Some(o) => Some(Lan::prepare(&repo, o)?),
        None => None,
    };
    let token = token()?;
    let listener = TcpListener::bind((std::net::Ipv4Addr::LOCALHOST, port)).map_err(err)?;
    listener.set_nonblocking(true).map_err(err)?;
    let host = listener.local_addr().map_err(err)?.to_string();
